//! Original instance-list DATA over two actual hidden-inclusive CODE phases.
//! The adapter does not grant source completion; only the private host can.
use std::{collections::{HashSet,BTreeMap},sync::Arc,io};
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_allow_annotations::PatternOperation,key_policy_control::{self as kc,Control},reactive_raw_policy_pages::RawPolicyPages,instance_list_policy::{self as policy,Judged},lint::{Site,AllowUse},dm::walk::{WalkKey,walk_key_using,cmp_keys}};
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn checked(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}checked(b,poll)?;pending}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
fn row<C:Control,T>(c:&mut C,v:&mut Vec<T>)->Result<(),C::Error>{if v.len()<v.capacity(){return Ok(())}let target=v.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;kc::reserve(c,||bound.checked_mul(std::mem::size_of::<T>())?.checked_add(128))?;v.try_reserve_exact(target-v.len()).map_err(|_|c.allocation_failed())?;if v.capacity()>bound{return Err(c.allocation_failed())}Ok(())}
struct FileRow{relative:String,key:WalkKey,judged:Judged,lines:Vec<(u32,String)>}
pub struct InstanceListData{sites:Vec<Site>,source_text:Vec<String>,allow_used:Vec<AllowUse>,allow_digests:BTreeMap<String,[u8;20]>}
impl InstanceListData{pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allow_used}pub fn allow_digests(&self)->&BTreeMap<String,[u8;20]>{&self.allow_digests}pub fn metadata(&self)->&'static crate::lint::Meta{&policy::META}pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.source_text.capacity().checked_mul(std::mem::size_of::<String>())?)?.checked_add(self.allow_used.capacity().checked_mul(std::mem::size_of::<AllowUse>())?)?;for s in &self.sites{for text in [&s.rule,&s.rel,&s.msg,&s.key,&s.ident]{n=n.checked_add(text.capacity())?;}}for s in &self.source_text{n=n.checked_add(s.capacity())?;}for a in &self.allow_used{for s in [&a.rel,&a.name,&a.code]{n=n.checked_add(s.capacity())?;}}for p in self.allow_digests.keys(){n=n.checked_add(2048+std::mem::size_of::<(String,[u8;20])>())?.checked_add(p.capacity())?;}Some(n)}}
fn normalized<C:Control>(text:&str,c:&mut C)->Result<String,C::Error>{let count=text.split_whitespace().try_fold(0usize,|n,_|{c.checkpoint()?;n.checked_add(1).ok_or_else(||c.overflow())})?;kc::reserve(c,||count.checked_mul(4*std::mem::size_of::<&str>())?.checked_add(text.len().checked_mul(4)?)?.checked_add(256))?;Ok(crate::util::normalize_ws(text))}
pub fn collect_from_pages(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<InstanceListData,Failure>{collect_using(pages,root,poll,None)}
pub fn collect_from_pages_with_patterns(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<InstanceListData,Failure>{collect_using(pages,root,poll,Some(patterns))}
fn collect_using(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<InstanceListData,Failure>{checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let keep=&phase.budget;let pending=(||{let mut work=PatternOperation{patterns,budget:keep,poll};let mut globals=HashSet::new();if !pages.for_each(&mut|_,views|{let local=views.allocation_budget(keep);let pending=(||{let file=views.source_file()?;let mut temporary=PatternOperation{patterns,budget:local,poll};for name in policy::globals_of_using(file,&mut temporary)?{work.checkpoint()?;if name!="/datum"&&!globals.contains(&name){kc::reserve(&mut work,||Some(2048))?;globals.insert(kc::own(&mut work,&name)?);}}Ok(true)})();finish(pending,local,poll)})?{return Err("instance-list singleton phase did not exhaust original hidden-inclusive CODE".into())}
let mut files=Vec::new();let mut digests=BTreeMap::new();if !pages.for_each(&mut|relative,views|{let local=views.allocation_budget(keep);let pending=(||{let file=views.source_file()?;let mut temporary=PatternOperation{patterns,budget:local,poll};let decls=policy::scan_decls_using(file,&mut temporary)?;let mut judged=Judged::default();let mut lines=Vec::new();for(owner,name,number)in decls{temporary.checkpoint()?;if crate::base_var_candidate_policy::is_singleton(&owner,&globals){continue}if let Some(value)=crate::allow::kept_using(file,number,policy::LINT,&mut temporary)?{let code=value.code.unwrap_or_default();work.reserve(code.capacity())?;let value=AllowUse{rel:kc::own(&mut work,relative)?,line:u32::try_from(value.line).map_err(|_|work.overflow())?,name:kc::own(&mut work,policy::LINT)?,code};if !judged.uses.contains(&value){row(&mut work,&mut judged.uses)?;judged.uses.push(value);}continue}let line=u32::try_from(number).map_err(|_|work.overflow())?;row(&mut work,&mut judged.decls)?;judged.decls.push((kc::own(&mut work,&owner)?,kc::own(&mut work,&name)?,line));if !lines.iter().any(|(n,_)|*n==line){let raw=file.raw();let text=normalized(raw.line(number),&mut temporary)?;work.reserve(text.capacity())?;row(&mut work,&mut lines)?;lines.push((line,text));}}
if !judged.uses.is_empty(){kc::reserve(&mut work,||Some(2048+std::mem::size_of::<(String,[u8;20])>()))?;digests.insert(kc::own(&mut work,relative)?,crate::captured_raw_file::source_allow_digest(file));}row(&mut work,&mut files)?;files.push(FileRow{relative:kc::own(&mut work,relative)?,key:walk_key_using(relative,&mut work)?,judged,lines});Ok(true)})();finish(pending,local,poll)})?{return Err("instance-list selected phase did not exhaust original hidden-inclusive CODE".into())}
kc::reserve(&mut work,||files.len().checked_mul(std::mem::size_of::<FileRow>())?.checked_add(128))?;files.sort_by(|a,b|cmp_keys(&a.key,&b.key));let output=std::cell::RefCell::new(InstanceListData{sites:Vec::new(),source_text:Vec::new(),allow_used:Vec::new(),allow_digests:digests});policy::finish_using(files.iter().map(|f|(f.relative.as_str(),&f.judged)),&mut work,&mut|value,c|{let mut out=output.borrow_mut();row(c,&mut out.allow_used)?;out.allow_used.push(AllowUse{rel:kc::own(c,&value.rel)?,line:value.line,name:kc::own(c,&value.name)?,code:kc::own(c,&value.code)?});Ok(())},&mut|index,relative,line,c|{let mut out=output.borrow_mut();let text=files[index].lines.iter().find(|(n,_)|*n==line).map(|(_,s)|s.as_str()).ok_or_else(||c.allocation_failed())?;row(c,&mut out.sites)?;row(c,&mut out.source_text)?;out.sites.push(Site{rule:kc::own(c,policy::LINT)?,rel:kc::own(c,relative)?,line,msg:String::new(),key:String::new(),ident:String::new()});out.source_text.push(kc::own(c,text)?);Ok(())})?;checked(keep,poll)?;Ok(output.into_inner())})();let pending=finish(pending,keep,poll);let pending=match pending{Ok(data)=>{let bytes=data.retained_charge().ok_or_else(||oom(root,"instance-list returned capacity overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(error)=>{drop(data);Err(error)}}},Err(error)=>Err(error)};phase.ok=pending.is_ok();drop(phase);finish(pending,root,poll)}
